"""Comprehensive Test Suite for 16-Layer Universal AI Protocol & Wire Decoders.
Verifies that ANY AI application worldwide across all 16 layers extracts prompts perfectly.
"""

import json
import base64
import unittest
import urllib.parse
from pathlib import Path

PROXY_DIR = Path(__file__).resolve().parents[1]
PARTS_DIR = PROXY_DIR / "gateway_proxy_parts"
PARTS = [
    "config_caches_rules.py",
    "helpers_prompts.py",
    "uploads_detect.py",
    "file_policy.py",
    "extract_office_backend.py",
    "responses_inject.py",
    "responses_addon.py",
]


def _load_proxy_namespace():
    ns = {"__name__": "universal_protocols_test"}
    for name in PARTS:
        path = PARTS_DIR / name
        exec(compile(path.read_text(encoding="utf-8"), str(path), "exec"), ns)
    return ns


class TestUniversalProtocols16Layers(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.ns = _load_proxy_namespace()
        cls.extract = cls.ns["extract_prompt_universal"]

    # ── Layer 0: Connect-RPC & gRPC-Web ───────────────────────────────────
    def test_layer_0_connect_rpc_protobuf(self):
        # Framed gRPC/Connect-RPC payload with UTF-8 string
        msg = b"Explain the theory of relativity"
        framed = bytes([0]) + len(msg).to_bytes(4, "big") + msg
        got = self.extract(framed, "application/connect+proto", host="api.anthropic.com", url="https://api.anthropic.com/PerformAction")
        self.assertIsNotNone(got)
        self.assertIn("theory of relativity", got)

    # ── Layer 1: SignalR / ASP.NET Core Hubs (\x1e) ───────────────────────
    def test_layer_1_signalr(self):
        payload = '{"arguments":[{"prompt":"Help me draft a formal apology email"}],"target":"chat"}\x1e'
        got = self.extract(payload.encode("utf-8"), "application/json", host="copilot.microsoft.com")
        self.assertEqual(got, "Help me draft a formal apology email")

    # ── Layer 2: Socket.IO / Engine.IO v2, v3, v4 ─────────────────────────
    def test_layer_2_socketio_event(self):
        # 42["chat_message", {"content": "Summarize today's financial news"}]
        payload = '42["chat_message", {"content": "Summarize today\'s financial news"}]'
        got = self.extract(payload.encode("utf-8"), "text/plain", host="chat.openwebui.internal")
        self.assertEqual(got, "Summarize today's financial news")

    def test_layer_2_socketio_namespace_and_string_arg(self):
        # 42/chat,["message", "How do transformers work?"]
        payload = '42/chat,["message", "How do transformers work?"]'
        got = self.extract(payload.encode("utf-8"), "text/plain", host="botpress.internal")
        self.assertEqual(got, "How do transformers work?")

    # ── Layer 3: Model Context Protocol (MCP) & JSON-RPC 2.0 ──────────────
    def test_layer_3_mcp_tools_call(self):
        payload = {
            "jsonrpc": "2.0",
            "method": "tools/call",
            "params": {
                "name": "sql_query_generator",
                "arguments": {"prompt": "Write a query to list all active employees in engineering"}
            },
            "id": 101
        }
        got = self.extract(json.dumps(payload).encode("utf-8"), "application/json", host="mcp.cursor.sh")
        self.assertEqual(got, "Write a query to list all active employees in engineering")

    def test_layer_3_mcp_prompts_get(self):
        payload = {
            "jsonrpc": "2.0",
            "method": "prompts/get",
            "params": {
                "name": "code_review",
                "arguments": {"user_input": "Review this pull request for race conditions"}
            },
            "id": 102
        }
        got = self.extract(json.dumps(payload).encode("utf-8"), "application/json", host="claude.desktop.internal")
        self.assertEqual(got, "Review this pull request for race conditions")

    # ── Layer 4: Platform-Specific Parsers ─────────────────────────────────
    def test_layer_4_chatgpt_messages(self):
        payload = {
            "action": "next",
            "messages": [
                {
                    "author": {"role": "user"},
                    "content": {"content_type": "text", "parts": ["What is quantum computing?"]}
                }
            ],
            "model": "gpt-4o"
        }
        got = self.extract(json.dumps(payload).encode("utf-8"), "application/json", host="chatgpt.com")
        self.assertEqual(got, "What is quantum computing?")

